const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let projects=[],token=sessionStorage.getItem('cloudmate-token')||'',base=localStorage.getItem('cloudmate-api')||'',docker=false,active='overview',logId=null;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.tm);window.tm=setTimeout(()=>$('#toast').style.display='none',5000)}
async function api(path,body){const r=await fetch(base+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Server request failed');return d}
function render(){const q=$('#search').value.toLowerCase(),f=$('#filter').value;$('#project-grid').innerHTML=projects.filter(p=>(p.name+' '+p.repo).toLowerCase().includes(q)&&(f==='all'||p.status===f)).map(p=>`<article class="project-card"><div class="card-body"><div class="card-top"><span class="app-icon">↗</span><span class="badge ${p.status==='Stopped'||p.status==='Failed'?'stopped':''}">● ${esc(p.status)}</span></div><h3>${esc(p.name)}</h3><div class="repo-line">◉ ${esc(p.repo.replace('https://github.com/',''))}</div><div class="tag-row"><span class="tag">${esc(p.detectedRuntime||p.runtime)}</span><span class="tag">⑂ ${esc(p.branch)}</span></div><div class="card-info"><span>Application port</span><b>${p.port}</b></div><div class="card-info"><span>Server port</span><b>${p.hostPort}</b></div></div><div class="card-foot"><span>${new Date(p.created*1000).toLocaleTimeString()}</span><button data-id="${esc(p.id)}">View logs ↗</button></div></article>`).join('')||`<div class="empty">${token?'No deployments yet. Deploy your first GitHub project.':'Connect your server to start deploying.'}<br><button class="primary" style="margin-top:18px" id="empty-action">${token?'Deploy a project':'Connect server'}</button></div>`;$('#empty-action')&&($('#empty-action').onclick=()=>token?openDeploy():connect());$('#total').textContent=projects.length;$('#project-count').textContent=projects.length;$('#running-count').textContent=projects.filter(p=>p.status==='Running').length+' running';$('#deployment-count').textContent=projects.filter(p=>p.status==='Running'||p.status==='Stopped').length;$('#server-count').textContent=docker?'1':'0';$('#engine').textContent=docker?'Connected':'Offline';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>detail(b.dataset.id));$('#lower').innerHTML=`<section class="panel"><div class="panel-heading"><h2>Deployment activity</h2></div>${projects.slice().reverse().slice(0,5).map(p=>`<div class="activity-item"><span class="event-icon">↗</span><div><strong>${esc(p.name)}</strong><p>${esc(p.status)}</p></div><time>${new Date(p.created*1000).toLocaleTimeString()}</time></div>`).join('')||'<p>Your real deployment events will appear here.</p>'}</section><section class="panel"><div class="panel-heading"><h2>Your infrastructure</h2><button id="connection">Manage ↗</button></div><div class="notice">${docker?'Docker Engine is connected. Builds and containers run on your server.':'Connect the CloudMate P2C server to build images and run containers.'}</div><p>API: ${esc(base||'Same server as this app')}</p></section>`;$('#connection').onclick=connect}
async function refresh(){if(!token){render();return}try{projects=await api('/api/projects');const h=await api('/api/health');docker=h.docker;render();if(logId&&$('#detail-dialog').open)await showLogs(logId)}catch(e){docker=false;$('#engine').textContent='Offline';if(!window.errorShown){toast('Server unavailable: '+e.message);window.errorShown=true}}}
function connect(){$('#detail-title').textContent='Connect your server';logId=null;$('#detail-content').innerHTML=`<p><a href="/cloudmate-p2c-server.zip" download>↓ Download the server package</a></p><p>Run the included CloudMate P2C server on your Docker host, then connect here. When this app is served by that server, leave the URL empty.</p><form id="connection-form"><label>Server API URL<input type="url" id="api-url" placeholder="https://deploy.example.com" value="${esc(base)}"></label><label>Server token<input type="password" id="api-token" autocomplete="off" required value="${esc(token)}"></label><div class="notice">Use HTTPS for remote connections. The token is kept only for this browser session. For this hosted interface, set CLOUDMATE_ORIGIN on the server to this page’s origin.</div><div class="modal-actions"><button class="primary">Test & connect ↗</button></div><p id="connect-error" role="status"></p></form>`;$('#connection-form').onsubmit=async e=>{e.preventDefault();const oldBase=base,oldToken=token;try{base=$('#api-url').value.trim().replace(/\/$/,'');if(base){const u=new URL(base);if(u.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(u.hostname))throw Error('Use HTTPS for a remote API');if(u.username||u.password||u.search||u.hash)throw Error('Enter a plain API origin')}token=$('#api-token').value;const h=await api('/api/health');if(!h.docker)throw Error('Server reached, but Docker is unavailable. Install/start Docker first.');docker=true;sessionStorage.setItem('cloudmate-token',token);localStorage.setItem('cloudmate-api',base);window.errorShown=false;$('#detail-dialog').close();await refresh();toast('Server connected')}catch(err){base=oldBase;token=oldToken;$('#connect-error').textContent=err.message}};$('#detail-dialog').showModal()}
function openDeploy(){if(!token||!docker)return connect();$('#deploy-dialog').showModal()}$('#new-project').onclick=openDeploy;document.querySelectorAll('.close').forEach(b=>b.onclick=()=>{logId=null;b.closest('dialog').close()});$('#detail-dialog').addEventListener('close',()=>logId=null);$('#search').oninput=render;$('#filter').innerHTML='<option value="all">All statuses</option>'+['Running','Queued','Cloning','Building','Starting','Failed','Stopped'].map(s=>`<option>${s}</option>`).join('');$('#filter').onchange=render;
$('#deploy-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('/api/projects',{repo:$('#repo').value.trim(),branch:$('#branch').value,runtime:$('#runtime').value,port:Number($('#port').value),hostPort:Number($('#host-port').value)});$('#deploy-dialog').close();await refresh();toast('Deployment queued. Follow progress in project logs.')}catch(err){$('#inspect-result').textContent=err.message}finally{b.disabled=false}};
$('#inspect').onclick=async()=>{try{const m=$('#repo').value.trim().match(/^https:\/\/github\.com\/([\w-]+)\/([\w.-]+)\/?$/);if(!m)throw Error('Enter a public GitHub repository URL');$('#inspect').disabled=true;const r=await fetch(`https://api.github.com/repos/${m[1]}/${m[2].replace(/\.git$/,'')}`);if(!r.ok)throw Error('GitHub lookup failed; check URL and rate limit');const d=await r.json();$('#branch').value=d.default_branch;$('#inspect-result').textContent=`✓ ${d.full_name} · ${d.language||'Runtime detected at build time'}`}catch(e){$('#inspect-result').textContent=e.message}finally{$('#inspect').disabled=false}};
async function showLogs(id){const d=await api('/api/projects/'+id+'/logs');if(logId===id&&$('#log-output'))$('#log-output').textContent=d.logs||'Waiting for build worker…'}
async function detail(id){const p=projects.find(p=>p.id===id);logId=id;$('#detail-title').textContent=p.name;$('#detail-content').innerHTML=`<p>Build output and application logs · server port ${p.hostPort}</p><pre id="log-output">Loading…</pre><div class="detail-actions"><button class="secondary" id="refresh-logs">Refresh logs</button>${p.container?'<button class="secondary" id="stop-container">Stop container</button>':''}</div>`;$('#refresh-logs').onclick=()=>showLogs(id).catch(e=>toast(e.message));if($('#stop-container'))$('#stop-container').onclick=async()=>{try{await api('/api/projects/'+id+'/stop',{});toast('Container stopped');await refresh()}catch(e){toast(e.message)}};$('#detail-dialog').showModal();try{await showLogs(id)}catch(e){toast(e.message)}}
function nav(v){active=v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#section-title').textContent=v==='servers'?'Your server':v==='activity'?'Deployment activity':'Your projects';$('#section-description').textContent=v==='servers'?'Connect the machine where your containers will run.':'Live data from your deployment server.';$('#project-grid').hidden=['servers','activity'].includes(v);$('.project-tools').hidden=['servers','activity'].includes(v);$('#lower').hidden=v==='projects';if(v==='servers')connect()}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>nav(b.dataset.view));$('#guide').onclick=$('#docs').onclick=e=>{e.preventDefault();logId=null;$('#detail-title').textContent='Deploy with CloudMate P2C';$('#detail-content').innerHTML='<p><a class="primary" href="/cloudmate-p2c-server.zip" download>↓ Download server package</a></p><p>Install the included server.py on a Linux host with Python 3.10+, Git, and Docker. Set CLOUDMATE_TOKEN, then start it. Open its port through an SSH tunnel, or place it behind an HTTPS reverse proxy.</p><pre>export CLOUDMATE_TOKEN="your-long-random-secret"\npython3 server.py</pre><p>Connect your server, paste a public GitHub URL, choose ports, and click Build & deploy. CloudMate P2C clones the code, builds an image, starts a container, and provides deployment logs. Python defaults to app.py; custom apps should include a Dockerfile.</p><div class="notice">The server must run on your machine; the hosted interface alone cannot run Docker. Deployment history currently lasts until the server process restarts; Docker containers survive restarts.</div>';$('#detail-dialog').showModal()};render();refresh();setInterval(refresh,4000);
